import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`product-listing`,heroTitle:`Create product listings that rank in minutes`,heroSubtitle:`Perplexity Computer researches your category, writes SEO-optimized copy, and delivers complete listings with keyword rationale and pricing benchmarks — automatically.`,inputUrlCta:`Optimize my listing`,inputUrlPlaceholder:`yourstore.com/product`,inputUrlPrefill:`Go to {url} and research this product and its category to build a complete, optimized product listing. (1) Identify the product type, target buyer, and competitive category — then research the top 10 best-selling listings in this category across major marketplaces for title structure, keyword usage, bullet point format, and description style. (2) Extract high-volume search keywords and long-tail phrases buyers use to find products like this — prioritize by search volume and purchase intent. (3) Write 3 SEO-optimized title variations using top keywords, following marketplace best practices for character length and keyword placement. (4) Write 5 compelling bullet points that lead with benefits, embed high-value keywords naturally, and address common buyer objections found in competitor reviews. (5) Write a full product description with keyword-rich copy, lifestyle use cases, and trust-building details. (6) Deliver a keyword rationale table showing which keywords were used, their estimated search volume, and where they appear. (7) Include pricing benchmarks from the top 10 competitors — average price, price range, and a recommended price position with reasoning. (8) Provide 5 ranking tips specific to this category — covering indexing, backend keywords, image optimization, and review strategy.`,heroOverlaySteps:[`Researching top-performing listings in your product category`,`Extracting high-volume keywords and analyzing competitor copy`,`Writing SEO-optimized titles, bullets, and descriptions`,`Complete listing with keyword rationale, pricing benchmarks, and ranking tips — ready to publish`],generatingSteps:[`Visiting {url} to analyze your product, category, and competitive landscape`,`Designing an agent to research top listings and extract high-volume keywords`,`Configuring SEO copywriting and pricing benchmark pipelines`,`Setting up listing deliverable with keyword rationale and ranking recommendations`],featureSectionTitle:`From product page to #1 listing`,featureCardTitles:[`Connects to your ecommerce stack`,`Listings you can publish today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Shopify, Google Sheets, Google Drive, Airtable, Notion — Computer plugs into your tools so keyword research, listing drafts, and pricing data flow into one workflow.`,`SEO-optimized titles. Benefit-led bullet points. Keyword-rich descriptions. Pricing benchmarks. Backend keyword suggestions. Computer delivers everything you need to list and rank.`],capabilitySectionTitle:`Your listing strategist, on autopilot`,capabilitySectionSubtitle:`Describe your product, step away, get back a publish-ready listing.`,capabilityCards:[{title:`Category Research`,description:`Computer can analyze the top 10 listings in your category — title structures, keyword patterns, bullet formats, and pricing — to show exactly what's winning.`},{title:`Keyword Optimization`,description:`Computer can extract high-volume search terms and long-tail phrases, rank them by purchase intent, and weave them naturally into every section of your listing.`},{title:`Pricing Benchmarks`,description:`Computer can pull competitor prices across your category — average, range, and premium tiers — and recommend a price position with reasoning tied to your product's strengths.`},{title:`Connect Your Tools`,description:`Computer can read from Shopify, Google Sheets, Airtable, Google Drive, and Notion — build workflows across your product catalog and listing operations.`},{title:`Knows Your Catalog`,description:`Computer can remember your brand voice, product line, past listings, and top-performing keywords across sessions — so every new listing builds on what already works.`},{title:`Ranking Alerts`,description:`Computer can monitor competitor listings and keyword trends weekly — and alert you when a rival changes pricing, a new keyword surges, or your listing needs a refresh.`}]});export{t as default};
